/**
 * Language switcher widget in the Pagelayer editor.
 *
 * The output of the switcher is generated by PHP. After each change of the settings the output is loaded via AJAX.
 */
const easy_language_pagelayer_switcher = {
	timers: {},
	html: {},
};

/**
 * Set the last known output before Pagelayer renders the widget template.
 *
 * @param {Object} el The Pagelayer element.
 */
window.pagelayer_render_pl_easy_language_switcher = function ( el ) {
	el.tmp = el.tmp || {};
	if ( easy_language_pagelayer_switcher.html[ el.id ] !== undefined ) {
		el.tmp.switcher = easy_language_pagelayer_switcher.html[ el.id ];
	} else {
		el.tmp.switcher = el.tmp.switcher || '';
	}
};

/**
 * Load the output after Pagelayer has rendered the widget.
 *
 * @param {Object} el The Pagelayer element.
 */
window.pagelayer_render_end_pl_easy_language_switcher = function ( el ) {
	clearTimeout( easy_language_pagelayer_switcher.timers[ el.id ] );
	easy_language_pagelayer_switcher.timers[ el.id ] = setTimeout( function () {
		jQuery.ajax( {
			url: easyLanguagePagelayerJsVars.ajax_url,
			type: 'POST',
			data: {
				action: 'easy_language_pagelayer_switcher',
				nonce: easyLanguagePagelayerJsVars.nonce,
				show_icons: el.atts.show_icons ? 1 : 0,
				hide_actual_language: el.atts.hide_actual_language ? 1 : 0,
			},
			success( data ) {
				easy_language_pagelayer_switcher.html[ el.id ] = data;
				el.tmp.switcher = data;
				el.$.find( '.easy-language-switcher-pagelayer' ).html( data );
			},
		} );
	}, 300 );
};
